  "stroke.add.width":{"description":"笔粗0.1–512图层局部像素。"},
  "stroke.add.tool":{"description":"栅格绘画工具；建议显式传入。","enum":["pencil","ink","eraser","soft","spray","mirror","dyna","calligraphy","line","rectangle","ellipse","polygon","polyline","bezier","gradient"]},
  "stroke.add.points":{"description":"图层局部点[[x,y],[x,y,pressure],...]；1–10000点，pressure=0–1。rectangle/ellipse为2个原始角点（支持figure约束，轮廓由引擎生成）；gradient恰好2点；line为2–10000点，首尾定线；polygon>=3，polyline>=2；bezier为起点+每段控制点1/2/终点，4–1024点且(点数-1)%3=0。 六支栅格笔及多重/动态画笔及直线支持[x,y,pressure,timeMs,tilt,rotation]，可省略末尾项；timeMs非递减且0–180000，省略按16ms/点；tilt/rotation=0–1，缺省0。speed按像素/ms归一化到0–1；rotation是笔方向角输入。其他工具仍为2–3项。 polygon/polyline/bezier的新笔画接入path.draw同一引擎，保存原始pathInput与最终笔刷points；填充仅polygon。"},
  "assistant.stroke.tool":{"description":"沿尺规的栅格画笔，默认ink。 mirror使用brushTool选主笔，投影主轨迹后复制副笔。 dyna先惯性过滤，再沿指定尺规投影；Mass/Drag默认0.5/0.15。 line按brushTool选择笔刷，首尾定直线，只接受直线尺规，angleStep须为0。","enum":["ink","pencil","soft","spray","eraser","calligraphy","mirror","dyna","line"]},
  "assistant.stroke.width":{"description":"笔粗0.1–512图层局部像素。"},
  "assistant.stroke.points":{"description":"1–10000个文档坐标[x,y]或[x,y,pressure]，pressure=0–1；投影后转换为图层局部。 六支栅格笔及多重/动态画笔及直线可传pressure/timeMs/tilt/rotation，格式与stroke.add.points相同。 line至少2点，首尾不能重合。"},
  "assistant.project.points":{"description":"1–10000个文档坐标[x,y]或[x,y,pressure]，pressure=0–1；只返回投影坐标。"},
  "assistant.create.points":{"description":"文档像素[x,y]，有限且abs<=1000000。普通直尺/无限/平行/曲线透视2点；消失点1点；椭圆/同心/鱼眼3点（轴两端+轴段内侧方）；双消失点3点（两消失点+预览中心）；样条4点（起点/终点/起柄/终柄）；透视网格/椭圆4点（按顺序凸四角）。简例见assistant.list.typeInfos。"},
  "assistant.create.type":{"description":"尺规类型。","enum":["ruler","infinite_ruler","parallel_ruler","ellipse","concentric_ellipse","vanishing_point","spline","perspective_grid","perspective_ellipse","two_vanishing_points","fisheye","curvilinear_perspective"]},
  "selection.polygon.points":{"description":"3–2048个文档像素顶点[[x,y],...]，闭合时连接首尾；不可为零面积，保留自交的偶奇填充规则。"},
  "selection.freehand.points":{"description":"3–2048个文档像素顶点[[x,y],...]，闭合时连接首尾；不可为零面积，保留自交的偶奇填充规则。"},
  "shape.freehand.points":{"description":"2–2048个图层局部像素点[[x,y],...]。"},
  "shape.freehand.mode":{"description":"徒手拟合方式，默认curve。","enum":["raw","curve","straight"]},
  "shape.freehand.precision":{"description":"简化误差0.25–32像素，默认2。"},
  "shape.calligraphy.width":{"description":"笔粗0.1–512图层局部像素，默认20。"},
  "shape.calligraphy.angle":{"description":"笔尖从+X顺时针0–180度，默认45。"},
  "comic.cut.angle":{"description":"划分水平/竖直/斜向的容差0–45度，默认15。"},
  "patch.apply.points":{"description":"1–4096个文档像素二维点[[x,y],...]，形成涂抹蒙版。"},
  "patch.apply.width":{"description":"涂抹蒙版笔粗1–256文档像素。"},
  "patch.apply.feather":{"description":"修补边缘羽化0–8像素，默认2。"},
  "patch.apply.searchRadius":{"description":"原尺寸纹理搜索半径整数16–1024px，默认64；逐层按scale缩放。扩大范围可帮助覆盖大物体，但增加局部外框和内存。"},
  "enclose.apply.points":{"description":"仅非贝塞尔：文档像素[[x,y],...]；rect/ellipse恰好2个对角点，lasso为3–2048点自动闭合，brush为1–2048点。与nodes互斥。"},
  "enclose.apply.width":{"description":"仅brush使用，笔粗整数1–256文档像素，默认32。"},
  "enclose.apply.feather":{"description":"羽化整数0–32文档像素，默认0；大于0时跳过AA。处理范围包含软边外扩，最多4194304像素。"},
  "enclose.apply.mode":{"description":"围合颜色条件，默认all。","enum":["all","transparent","color","color_or_transparent","not_color","not_transparent","not_color_or_transparent"]},
  "enclose.apply.regionColor":{"description":"颜色筛选目标#AARRGGBB，默认#FFFFFFFF。"},
  "colorize.stroke.points":{"description":"1–4096个蒙版局部像素二维点[[x,y],...]；当前根蒙版空间等同文档。"},
  "colorize.stroke.width":{"description":"线索笔粗0.1–256蒙版局部像素。"},
  "colorize.stroke.color":{"description":"#AARRGGBB；erase=false时必填且AA不能为00。"},
  "colorize.palette.action":{"description":"调色板动作。transparent须传transparent布尔值；remove删除该色全部线索。","enum":["transparent","remove"]},
  "colorize.settings.settings":{"description":"部分更新对象：useEdgeDetection:boolean默认false；edgeDetectionSize:0–100px默认4，0不检测；fuzzyRadius:0–500px默认0，三箱Gaussian近似sigma（缺口提示约2倍）；cleanUpAmount:0–1默认0，强度越大越易清理小异色竞争溢出块。保留threshold:1–254整数默认180、gapClose:0–8整数默认0、limitBounds:false、editKeys:true、showOutput:true。只传修改字段；求解字段改变后update，线索保留。"},
  "assistant.settings.settings":{"description":"{visible:boolean,snapping:boolean,onlySelected:boolean,thresholdDp:4–64}；只传要改字段，全局visible=false不关闭吸附。"},
  "path.create.style":{"description":"可选{fill,stroke,strokeWidth,opacity,objectStyle}，高级样式结构见shape.style_info。对象和柄坐标同处对象局部空间。"},
  "shape.freehand.style":{"description":"新路径样式{fill,stroke,strokeWidth,opacity,objectStyle}，objectStyle结构查shape.style_info。接续使用已有目标的样式；要更换结果样式，成功后调用shape.style。"},
  "shape.style.style":{"description":"样式部分对象{fill:#AARRGGBB,stroke:#AARRGGBB,strokeWidth:0.1–512,opacity:0–1,cornerRadius:0–16384,objectStyle:{...}}。cornerRadius仅矩形。objectStyle支持fillRule:nonzero/evenodd,strokeCap:butt/round/square,strokeJoin:miter/round/bevel,miterLimit:1–100,dashArray:[]或2–16个偶数正长度(0.1–4096局部像素),dashOffset:±1000000,fillOpacity/strokeOpacity:0–1,fillGradient/strokeGradient:null清除或{type:linear/radial,start:[x,y],end:[x,y],stops:[[0,#AARRGGBB],...,[1,#AARRGGBB]]}。渐变2–16站、位置严格递增含0/1、坐标对象局部、起终点不同；径向起点为圆心、终点定义半径。结构也见shape.style_info。"},
  "comic.frame.style":{"description":"样式对象{fill:\"#AARRGGBB\",stroke:\"#AARRGGBB\",strokeWidth:0.1–512,opacity:0–1}；只传要改字段。"},
  "reference.style.style":{"description":"{opacity:0–1,saturation:0–1,visible:boolean,locked:boolean,keepAspect:boolean,name:string}；锁定时只允许单改locked。"},
  "shape.create.shape":{"description":"{kind:line/rectangle/ellipse/polygon/path,points:[[x,y],...],fill:\"#AARRGGBB\",stroke:\"#AARRGGBB\",strokeWidth:0.1–512,opacity:0–1,matrix:[a,b,c,d,tx,ty]}；图层局部；前三类2点，多边形3–2048点；path须commands=[\"L\",\"C\",...]和可选closed，L耗1后续点/C耗3点，最多2048段/6145点。 rectangle可传cornerRadius:0–16384，按短边一半限制，保持可编辑。 path另支持M(耗1点的新子路径起点)/Z(不耗点闭合当前子路径，之后须M或结束)，多子路径时closed=false；nodeModes为各子路径去除重复闭合端点后的全局节点类型。最多64子路径、总2048段/6145几何点。可传objectStyle，高级样式见shape.style_info。"},
  "path.edit.edits":{"description":"1–64动作。原动作move_node{node,x,y}/move_handle{node,side:in/out,x,y}/node_type{node,type:corner/smooth/symmetric}/delete_node{node}/insert_node{segment,t}/segment_type{segment,type:line/curve}/closed{value}。x/y与批量dx/dy均为对象局部像素坐标或位移；node为path.nodes.nodes的全局索引；可传subpath后node/segment为局部索引；closed默认子路径0。批量move_nodes{nodes:[全局索引],dx,dy}/node_types{nodes,type}/delete_nodes{nodes}，每组索引不重复。断开/连接用path.topology；动作顺序生效，改变节点数后重读path.nodes。"},
  "selection.bezier_edit.edits":{"description":"1–64动作：{action:\"move_node\",node,x,y}；move_handle需node/side=in|out/x/y；node_type需node/type=corner|smooth|symmetric；insert_node需segment/t=0.01–0.99默认0.5；delete_node需node；segment_type需segment/type=line|curve。索引零基，按顺序执行。坐标为文档像素，始终闭合，不支持closed动作。"},
  "path.create.nodes":{"description":"图层局部像素节点[{x,y,in:[x,y],out:[x,y],type:corner/smooth/symmetric}]；柄是绝对坐标，非偏移。开放2–2049节点、闭合1–2048节点，须有非零几何，默认corner。"},
  "selection.bezier_create.nodes":{"description":"2–2048个文档像素节点[{x,y,in:[x,y],out:[x,y],type:corner/smooth/symmetric}]；柄是绝对坐标；始终闭合且面积非零。"},
  "selection.contiguous.mode":{"description":"默认replace；add覆盖相加封顶，subtract相减截零，intersect取小值，xor取差绝对值。无已有选区时add/xor创建，subtract/intersect为空；统一8位蒙版。","enum":["replace","add","subtract","intersect","xor"]},
  "selection.similar.mode":{"description":"默认replace；add覆盖相加封顶，subtract相减截零，intersect取小值，xor取差绝对值。无已有选区时add/xor创建，subtract/intersect为空；统一8位蒙版。","enum":["replace","add","subtract","intersect","xor"]},
  "selection.magnetic_trace.mode":{"description":"选区组合模式，默认replace。；支持xor异或，与软选区组合时保存最终覆盖率蒙版。","enum":["replace","add","subtract","intersect","xor"]},
  "selection.edit.action":{"description":"作用于与选区相交的整笔结构化笔画。MOVE需dx/dy，SCALE需factor，ROTATE需degrees且仅矩形选区；COPY位移固定20px。","enum":["DELETE","COPY","MOVE","SCALE","ROTATE"]},
  "dock.command.command":{"description":"set_visible需panel/enabled；expand/collapse需panel；collapse_all/restore无附加参数；set_confirmation需enabled。","enum":["set_visible","expand","collapse","collapse_all","restore","set_confirmation"]},
  "view.command.command":{"description":"只改变显示，返回实际预览；旋转每次15度，镜像为切换。","enum":["zoom_in","zoom_out","zoom_100","fit","fit_width","fit_height","rotate_right","rotate_left","reset_rotation","mirror","reset_display","refresh"]},
  "view.zoom_tool.mode":{"description":"只设置手机缩放工具方向，不立即缩放。","enum":["in","out","toggle"]},
