  "enclose.apply.shape":{"description":"lasso/rect/ellipse/brush/bezier；shape必填，bezier只传nodes，其他只传points。","enum":["lasso","rect","ellipse","brush","bezier"]},
  "enclose.apply.nodes":{"description":"仅bezier：2–2048节点[{x,y,in?:[x,y],out?:[x,y],type?:corner|smooth|symmetric}]，控制柄为绝对文档坐标，自动闭合含末段。2节点须带柄产生面积，普通直线闭合至少3节点。"},
  "enclose.apply.expand":{"description":"扩展/收缩整数-64–64文档像素，默认0；负数收缩。围合初始范围限制分区，后处理允许向外扩边。"},
  "enclose.apply.antialias":{"description":"边缘抗锯齿强度0–1，默认1；0硬边。使用共享1px边界平滑；feather>0时跳过，不重复乘几何软边。"},
  "enclose.apply.opacitySpread":{"description":"软覆盖硬度0–100%，默认100（二值）；软覆盖需tolerance>0。按clamp((T-d)*255*100/(T*(100-hardness)),0,255)计算；负条件和invert保留255-覆盖率。"},
  "enclose.apply.stopAtDarkest":{"description":"布尔，默认false；仅expand>0：共享八邻域亮度/alpha脊线门控，阻止扩展跨越更亮/更透明的像素。基于固定参考，不宣称与Krita逐像素等同。"},
  "enclose.apply.reference":{"description":"current当前层原始像素；visible可见层合成（默认）；labels合成匹配colorLabels的可见内容层/组；均排除背景和辅助对象。","enum":["current","visible","labels"]},
  "enclose.apply.colorLabels":{"description":"reference:labels时按标签ID取参考，默认[1]；非空去重整数0–8，先用layer.properties设置。未匹配可见内容明确报错。"},
  "enclose.apply.fillType":{"description":"solid纯色（默认）或pattern；图案透明度和当前选区覆盖率都会保留。","enum":["solid","pattern"]},
  "enclose.apply.pattern":{"description":"{kind:checker|stripes|dots|image,foreground/background:#AARRGGBB,tileSize:4–128整数默认16,scale:0.1–16默认1,angle:-360–360度默认0,offset:[dx,dy]文档px默认[0,0],asset?:UUID}；image资产先brush.resource.import(kind:texture)，1–512px。文档原点统一平铺，不按区域重置；图片原色/alpha保留。"},
  "enclose.apply.blend":{"description":"当前目标层像素内混合，随后才按图层opacity/blend合成整图；默认normal。erase:true时必须normal（DST_OUT）。固化overlay与blend一同重放。","enum":["normal","multiply","screen","overlay","darken","lighten","add","difference","exclusion","hard_light","soft_light","color_dodge","color_burn","hue","saturation","color","luminosity"]},
  "enclose.apply.erase":{"description":"默认false；true按纯色或图案alpha擦除目标层，须blend:normal；opacity0或无有效覆盖changed=false，不新增历史。"},
  "enclose.apply.color":{"description":"非擦除必填#AARRGGBB纯色；fillType:pattern时使用pattern前/背景或图片原色，color仍用于统一调用协议。"},
  "enclose.apply.invert":{"description":"默认false；在初始围合内使用255-覆盖率反选，再进行扩缩及羽化/AA。"},
  "enclose.apply.gapClose":{"description":"非all条件使用整数0–8文档px，默认0；形态学开运算断开窄通道后恢复已选软覆盖。all须0。"},
  "assistant.create.visible":{"description":"默认true；false不显示此尺规，也不参与吸附。"},
  "assistant.create.enabled":{"description":"默认true；false保留显示但不参与吸附。"},
  "assistant.create.locked":{"description":"默认false；true不能编辑/删除，更新只能单改locked解锁。"},
  "assistant.create.subdivisions":{"description":"默认10；ruler刻度0–100，perspective_grid网格1–100。"},
  "assistant.create.rays":{"description":"预览线组数整数，默认16；fisheye/curvilinear_perspective为4–16，其余4–64；不限制实际可吸附方向数量。"},
  "assistant.create.localEnabled":{"description":"默认false；true必须同时给localBounds或使用已保存矩形。只允许矩形内起笔，锁定后可越界。"},
  "assistant.create.localBounds":{"description":"文档矩形{x,y,width,height}：有限数，width/height>=0.01，两角abs坐标<=1000000；可与localEnabled一起创建/更新，随整体移动/画布偏移平移。"},
  "assistant.create.fixedLength":{"description":"默认0自由长度；正值仅ruler可用，按lengthUnit/unitDpi换算后0.01–1000000像素。保持起点和方向调整终点；拖动仍保持长度。"},
  "assistant.create.lengthUnit":{"description":"固定长度单位px/mm/cm/in/pt，默认px；物理单位使用该尺规保存的unitDpi换算。","enum":["px","mm","cm","in","pt"]},
  "assistant.create.unitDpi":{"description":"每尺规物理单位换算DPI，默认96，有限1–2400；不是作品打印DPI。"},
  "assistant.create.useVertical":{"description":"默认true；two_vanishing_points在两消失点方向外允许与地平线垂直的第三方向；预览中心不改变消失点。"},
  "crop.geometry.x":{"description":"裁剪框左上角文档整数像素，默认0，±16384；允许负数时须allowGrow=true。"},
  "crop.geometry.y":{"description":"裁剪框左上角文档整数像素，默认0，±16384；允许负数时须allowGrow=true。"},
