  "crop.geometry.allowGrow":{"description":"默认true，可在画布外建立裁剪框；false要求框完全在画布内，API越界拒绝。"},
  "crop.geometry.lockWidth":{"description":"默认false；true以fixedWidth覆盖请求宽度，与lockRatio互斥。"},
