  "brush.preset.save.width":{"description":"保存预设笔粗，0.1–512px，默认6；面板加载时应用；stroke.add仍传本次width。"},
  "brush.preset.save.opacity":{"description":"保存预设不透明度，0–1，默认1；面板加载时应用；stroke.add可显式传本次opacity。"},
  "mirror.stroke.points":{"description":"图层局部点[x,y,pressure,timeMs,tilt,rotation]，可省略末尾四项；1–10000点、压力/倾斜/方向0–1；时间非递减0–180000ms，省略按16ms/点。主轨迹处理一次，再复制。"},
  "mirror.stroke.width":{"description":"笔粗0.1–512图层局部像素。"},
  "mirror.stroke.axisX":{"description":"多重画笔对称中心的图层局部x坐标；默认当前画布尺寸的一半，须在画布尺寸范围内。"},
  "mirror.stroke.axisY":{"description":"多重画笔对称中心的图层局部y坐标；默认当前画布尺寸的一半，须在画布尺寸范围内。"},
  "stroke.add.axisX":{"description":"多重画笔对称中心的图层局部x坐标；默认当前画布尺寸的一半，须在画布尺寸范围内。"},
  "stroke.add.axisY":{"description":"多重画笔对称中心的图层局部y坐标；默认当前画布尺寸的一半，须在画布尺寸范围内。"},
  "assistant.stroke.axisX":{"description":"多重画笔对称中心的图层局部x坐标；默认当前画布尺寸的一半，须在画布尺寸范围内。"},
  "assistant.stroke.axisY":{"description":"多重画笔对称中心的图层局部y坐标；默认当前画布尺寸的一半，须在画布尺寸范围内。"},
  "dyna.stroke.points":{"description":"原始图层局部点[x,y,pressure,timeMs,tilt,rotation]，末尾四项可省略；1–10000点、压力/倾斜/方向0–1；时间非递减0–180000ms，省略按16ms/点。禁止把已过滤轨迹当原始输入，否则会再计算惯性。 高Mass且采样很少时位移会小，须传足够密集的原始采样。"},
  "dyna.stroke.width":{"description":"笔粗0.1–512图层局部像素。"},
  "dyna.stroke.mass":{"description":"动态画笔Mass，0–1，默认0.5；实际质量1+159×Mass，逐采样积分。"},
  "dyna.stroke.drag":{"description":"动态画笔Drag，0–1，默认0.15；阻尼0.5×Drag²，保留原有语义。"},
  "assistant.stroke.mass":{"description":"动态画笔Mass，0–1，默认0.5；实际质量1+159×Mass，逐采样积分。"},
  "assistant.stroke.drag":{"description":"动态画笔Drag，0–1，默认0.15；阻尼0.5×Drag²，保留原有语义。"},
  "stroke.add.mass":{"description":"动态画笔Mass，0–1，默认0.5；实际质量1+159×Mass，逐采样积分。"},
  "stroke.add.drag":{"description":"动态画笔Drag，0–1，默认0.15；阻尼0.5×Drag²，保留原有语义。"},
  "line.geometry.points":{"description":"图层局部采样[x,y,pressure,timeMs,tilt,rotation]，末尾四项可省略；2–10000点，首尾定线，间点保留沿线的传感器变化。压力/倾斜/方向0–1；timeMs非递减0–180000，省略按16ms/点。起终点不能重合；最终线段角度/尺规按文档空间计算。"},
  "line.draw.points":{"description":"图层局部采样[x,y,pressure,timeMs,tilt,rotation]，末尾四项可省略；2–10000点，首尾定线，间点保留沿线的传感器变化。压力/倾斜/方向0–1；timeMs非递减0–180000，省略按16ms/点。起终点不能重合；最终线段角度/尺规按文档空间计算。"},
  "line.draw.width":{"description":"笔粗0.1–512图层局部像素；矢量层作为描边宽度。"},
  "line.draw.brush":{"description":"共享dab-v1部分配置，结构见brush.info；仅绘画层。直线关闭weighted/stabilizer和定时airbrush，保留pixel_perfect、笔尖、纹理及动态曲线。"},
  "figure.geometry.points":{"description":"两个原始图层局部点[[x0,y0],[x1,y1]]。默认为拖拽起角和终角；drawFromCenter=true为中心与边缘。固定宽高/比例在这两个原始点上求最终边界；不要传已约束的轮廓。栅格笔刷轮廓自动闭合、压力固定1，非自由指针轨迹；轮廓最多10000采样，过长会明确拒绝。"},
  "figure.geometry.tool":{"description":"本入口的几何类型。","enum":["rectangle","ellipse"]},
  "figure.draw.points":{"description":"两个原始图层局部点[[x0,y0],[x1,y1]]。默认为拖拽起角和终角；drawFromCenter=true为中心与边缘。固定宽高/比例在这两个原始点上求最终边界；不要传已约束的轮廓。栅格笔刷轮廓自动闭合、压力固定1，非自由指针轨迹；轮廓最多10000采样，过长会明确拒绝。"},
  "figure.draw.tool":{"description":"本入口的几何类型。","enum":["rectangle","ellipse"]},
  "figure.draw.brush":{"description":"仅绘画层outline=brush使用共享dab-v1部分配置，结构见brush.info；保留笔尖、纹理和动态曲线，关闭weighted/stabilizer与定时airbrush，pixel_perfect可用。"},
  "figure.draw.width":{"description":"描边宽0.1–512图层局部像素；无描边时仍须传有效值。"},
  "path.geometry.tool":{"description":"栅格路径类型，绘画层专用。","enum":["polygon","polyline","bezier"]},
  "path.geometry.points":{"description":"图层局部原始控制点[[x,y],...]；polygon:3–2048点并自动闭合；polyline:2–2048点且保持开放；bezier:4–1024点，起点+重复的两个控制点和终点三元组(1+3n)。可含旧式第三项压力，但几何笔刷压力固定1；不接受触摸时间/倾角。笔刷弧长采样最多10000点，超限明确拒绝。"},
  "path.geometry.outline":{"description":"默认brush=当前共享笔刷；basic=普通颜色描边；none仅polygon且填充非空。brush/brushPresetId只在brush描边有效。","enum":["brush","basic","none"]},
  "path.geometry.figureFill":{"description":"完整填充对象，默认{mode:none}。mode:none/solid/pattern；solid可传color:#AARRGGBB（缺省本次color）。pattern={kind:checker/stripes/dots/image,tileSize:4–128整数(内置图案),foreground:#AARRGGBB,background:#AARRGGBB,scale:0.1–16,angle:-360–360,offset:[dx,dy]}；默认checker/16/本次color/透明/1/0/[0,0]，offset是图层局部像素且绝对值<=1000000。image必须asset（1–512px RGBA图片，原色平铺，tileSize/前背景色不染色）；取brush.resources(kind=texture)或导入返回asset。矢量仅none/solid。未知字段或不属于当前模式的color/pattern/asset拒绝。 本入口仅polygon支持solid/pattern；polyline/bezier只能none。"},
  "path.draw.tool":{"description":"栅格路径类型，绘画层专用。","enum":["polygon","polyline","bezier"]},
  "path.draw.points":{"description":"图层局部原始控制点[[x,y],...]；polygon:3–2048点并自动闭合；polyline:2–2048点且保持开放；bezier:4–1024点，起点+重复的两个控制点和终点三元组(1+3n)。可含旧式第三项压力，但几何笔刷压力固定1；不接受触摸时间/倾角。笔刷弧长采样最多10000点，超限明确拒绝。"},
  "path.draw.outline":{"description":"默认brush=当前共享笔刷；basic=普通颜色描边；none仅polygon且填充非空。brush/brushPresetId只在brush描边有效。","enum":["brush","basic","none"]},
  "path.draw.figureFill":{"description":"完整填充对象，默认{mode:none}。mode:none/solid/pattern；solid可传color:#AARRGGBB（缺省本次color）。pattern={kind:checker/stripes/dots/image,tileSize:4–128整数(内置图案),foreground:#AARRGGBB,background:#AARRGGBB,scale:0.1–16,angle:-360–360,offset:[dx,dy]}；默认checker/16/本次color/透明/1/0/[0,0]，offset是图层局部像素且绝对值<=1000000。image必须asset（1–512px RGBA图片，原色平铺，tileSize/前背景色不染色）；取brush.resources(kind=texture)或导入返回asset。矢量仅none/solid。未知字段或不属于当前模式的color/pattern/asset拒绝。 本入口仅polygon支持solid/pattern；polyline/bezier只能none。"},
  "path.draw.brush":{"description":"共享dab-v1部分配置，结构见brush.info。笔尖/纹理/动态曲线与预设共用；几何采样固定压力1、倾角/旋转0、合成时间，weighted/stabilizer/airbrush停驻关闭，pixel_perfect可用。"},
  "path.topology.action":{"description":"break_node=复制该节点后断开并保留两侧曲线；break_segment=删除该节点出发的一段；join=连段或闭合；merge=端点位置取中点，保留两侧柄偏移。","enum":["break_node","break_segment","join","merge"]},
  "path.topology.at":{"description":"零起始[子路径索引,该子路径节点索引]，取path.nodes.subpaths。break动作只传at，join/merge只传first和second。"},
  "path.topology.first":{"description":"零起始[子路径索引,该子路径节点索引]，取path.nodes.subpaths。break动作只传at，join/merge只传first和second。"},
  "path.topology.second":{"description":"零起始[子路径索引,该子路径节点索引]，取path.nodes.subpaths。break动作只传at，join/merge只传first和second。"},
  "path.topology.id":{"description":"目标kind=path对象ID，取shape.list；操作绑定当前documentId/expectedRevision。"},
  "path.topology.layerId":{"description":"可见且未锁定的kind=vector层ID，取layer.list；不可修改锁定/隐藏对象。"},
  "path.convert.layerId":{"description":"可见且未锁定的kind=vector层ID，取layer.list；不可修改锁定/隐藏对象。"},
  "path.combine.layerId":{"description":"可见且未锁定的kind=vector层ID，取layer.list；不可修改锁定/隐藏对象。"},
  "path.convert.ids":{"description":"同矢量层的不重复对象ID数组，取shape.list.shapes[].id；convert至少1，combine至少2且全部为path。combine按数组首对象保留ID、样式和局部坐标。"},
  "path.combine.ids":{"description":"同矢量层的不重复对象ID数组，取shape.list.shapes[].id；convert至少1，combine至少2且全部为path。combine按数组首对象保留ID、样式和局部坐标。"},
  "shape.freehand.optimizeRaw":{"description":"默认false保留去除连续重复后的Raw采样；true用rawPrecision误差约束减点，仅mode=raw生效。"},
  "shape.freehand.rawPrecision":{"description":"Raw优化误差，0.25–32图层局部像素，默认1，独立于Curve精度。"},
  "shape.freehand.optimizeCurve":{"description":"默认true，用分段最小二乘拟合减段；false逐采样段三次插值，保留每个采样位置，仅mode=curve生效。"},
  "shape.freehand.curvePrecision":{"description":"曲线拟合误差0.25–32图层局部像素；省略沿用precision（默认2），仅优化Curve生效。"},
  "shape.freehand.combineAngle":{"description":"straight模式允许合并的相邻转角0–90度，默认0关闭额外角度合并；先按precision做距离简化，合并还须前向且所有原始采样到合并弦的偏差<=precision，避免压平回头或弧线。"},
  "shape.freehand.startEndpoint":{"description":"可选{id:PATH_ID,subpath:零起始子路径,node:局部端点索引}，取同层path.nodes.subpaths，仅开放、可见、未锁定路径端点。points仍是图层局部采样；精确接点和对象矩阵由插件处理。不允许同一个端点用于两端，closed须false；接回同路径的另一端自动闭合。起点目标优先保留ID/样式，否则使用终点目标；合并消耗其他目标对象但保留其未连接子路径。"},
  "shape.freehand.endEndpoint":{"description":"可选{id:PATH_ID,subpath:零起始子路径,node:局部端点索引}，取同层path.nodes.subpaths，仅开放、可见、未锁定路径端点。points仍是图层局部采样；精确接点和对象矩阵由插件处理。不允许同一个端点用于两端，closed须false；接回同路径的另一端自动闭合。起点目标优先保留ID/样式，否则使用终点目标；合并消耗其他目标对象但保留其未连接子路径。"},
  "shape.align.ids":{"description":"非空且不重复的同层形状ID数组（shape.list取得），仅可见未锁定对象。align选区范围>=2/画布>=1，distribute>=3，shear>=1；整个操作一次撤销。"},
  "shape.distribute.ids":{"description":"非空且不重复的同层形状ID数组（shape.list取得），仅可见未锁定对象。align选区范围>=2/画布>=1，distribute>=3，shear>=1；整个操作一次撤销。"},
  "shape.shear.ids":{"description":"非空且不重复的同层形状ID数组（shape.list取得），仅可见未锁定对象。align选区范围>=2/画布>=1，distribute>=3，shear>=1；整个操作一次撤销。"},
  "shape.align.mode":{"description":"按画布轴和变换后的路径轮廓范围对齐，不计描边宽度。","enum":["left","center_x","right","top","center_y","bottom"]},
  "shape.align.reference":{"description":"selection默认，以所选轮廓联合范围为基准，>=2；canvas以画布0,0,width,height为基准，>=1。图层及父组的位移、旋转、缩放均计入。","enum":["selection","canvas"]},
  "shape.distribute.mode":{"description":"按画布轴分布；边/中心固定首尾坐标均分，gap_x/gap_y按左/顶边排序、固定首尾对象并均分间距；同坐标稳定排序，负间距表示重叠，不计描边。","enum":["left","center_x","right","gap_x","top","center_y","bottom","gap_y"]},
  "shape.shear.shearX":{"description":"横向剪切系数，有限值−100..100；x增加shearX*(y-pivotY)。与shearY同时应用，奇异矩阵拒绝。"},
  "shape.shear.shearY":{"description":"纵向剪切系数，有限值−100..100；y增加shearY*(x-pivotX)。水平剪切示例shearX:0.25,shearY:0。"},
  "shape.shear.pivot":{"description":"可选[x,y]，图层局部支点，有限坐标±1000000；默认所选对象轮廓联合范围中心。与对齐/分布的画布轴语义不同。"},
  "shape.calligraphy.samples":{"description":"2–1000个{x,y,time,pressure?}；x/y为图层局部像素±1000000，time为非递减毫秒0..1e12，pressure0–1默认1。useTilt=true每点另需tilt:0–90（离竖直倾角）和orientation:0–360（从图层+X顺时针），笔尖垂直倾斜方向；直立保持本笔最近方向。跟随模式按累计鼠标距离沿路径弧长前进，最多1000个中心点、间隔<=4局部像素。"},
  "shape.calligraphy.mass":{"description":"矢量书法质量0–20，默认0；惯性质量为mass²+1，逐输入点积分。跟随模式不参与，区别于栅格dyna的0–1质量映射。"},
  "shape.calligraphy.drag":{"description":"阻力0–1，默认1，旧速度乘(1-drag)；越大越抑制惯性。Mass=0/Drag=1保持直接输入；收笔不强制跳到鼠标终点。跟随模式不参与。"},
  "shape.calligraphy.useTilt":{"description":"默认false固定自定义角度；true使用每点tilt/orientation决定笔尖方向，并与fixation混合。Android交互要求数位笔提供AXIS_TILT与AXIS_ORIENTATION，缺轴明确提示。"},
  "shape.calligraphy.followPath":{"description":"默认false自由书写；true须给followPathId，按鼠标累计距离沿所选子路径前进，从其端点开始。路径保留，笔画为独立可编辑闭合轮廓；此模式Mass/Drag/smoothing不参与。"},
  "shape.calligraphy.followPathId":{"description":"followPath=true必填，同目标矢量层的可见kind:path对象UUID，取shape.list。只读导引可使用锁定路径；绘制所在图层与父组须可见未锁定。"},
  "shape.calligraphy.followSubpath":{"description":"零起始子路径索引，默认0，取path.nodes.subpaths。只跟随该子路径，不跳到其他轮廓；闭合路径只走一圈。配置档不保存这个工程引用。"},
  "shape.calligraphy.followReverse":{"description":"默认false从子路径起点开始；true从终点反向前进。达到路径末端后停止延长，输入点仍按约束校验。"},
  "shape.calligraphy.profileId":{"description":"可选配置档UUID，取calligraphy.profiles；先装载档中完整参数，再以本次显式设置覆盖。路径ID与子路径仍由本次请求指定；最终几何保存后不依赖配置档。"},
  "shape.calligraphy.smoothing":{"description":"0–1，默认0，惯性后的时间指数平滑；跟随模式不参与，避免切过路径转角。"},
  "calligraphy.profile.get.id":{"description":"配置档UUID，取calligraphy.profiles.profiles[].id；save省略新建、提供则保存到此UUID，get/delete不存在明确报错。"},
