  "selection.coverage.y":{"description":"有限文档像素坐标，查询像素中心请加0.5；画布外覆盖率为0。"},
  "selection.contiguous.reference":{"description":"默认visible。current读取layerId原始内容，忽略本层及祖先组透明度/混合；visible合成全部可见内容；labels仅合成匹配标签可见层，保留组变换/透明度/混合。均不含背景、尺规、参考图片和蒙版编辑线索。","enum":["current","visible","labels"]},
  "selection.contiguous.colorLabels":{"description":"颜色标签整数数组，1–9项且不重复，默认[1]，仅labels参考使用。0无标签，1蓝，2绿，3黄，4橙，5红，6紫，7灰，8棕；匹配非零标签组包括其可见子层，0只匹配无标签内容层。"},
  "selection.contiguous.opacitySpread":{"description":"覆盖硬度整数0–100%，默认100：容差内全选。降低硬度时覆盖率clamp((T-d)*255*100/[T*(100-hardness)],0,255)；T=tolerance*255/100，d为预乘RGBA最大通道差。软覆盖需要tolerance>0；boundaryMode反转覆盖曲线。"},
  "selection.contiguous.antialias":{"description":"边界抗锯齿强度0..1，默认1；1px十字邻域边界平滑，中心权重4、邻居各1；feather>0时跳过，避免重复平滑。"},
  "selection.contiguous.feather":{"description":"羽化半径整数0..32文档像素，默认0；三次盒滤波近似高斯。先扩展/收缩再羽化，之后组合。"},
  "selection.contiguous.expand":{"description":"扩展/收缩整数-64..64文档像素，默认0。正数扩展、负数收缩；结果裁到bounds/查找范围。"},
  "selection.contiguous.stopAtDarkest":{"description":"默认false，仅expand>0起效：8邻域扩展需下一像素更不透明或等透明，且更暗或等亮（上一像素全透明时不比较亮度）。不向局部暗峰后的亮区或透明度下降区传播；保留原覆盖率，最大范围仍受expand限制。不改变初始颜色搜索。"},
  "selection.contiguous.bounds":{"description":"可选查找范围{x,y,width,height}文档像素整数，尺寸>0；裁到画布后最多4194304像素。颜色搜索、扩展、羽化和AA都限制在此范围内。"},
  "selection.contiguous.limitToSelection":{"description":"默认false；true需现有选区，搜索仅用非零覆盖范围，最终覆盖率与原选区逐点取较小值。没有bounds时使用原选区外框作为查找范围。"},
  "selection.similar.reference":{"description":"默认visible。current读取layerId原始内容，忽略本层及祖先组透明度/混合；visible合成全部可见内容；labels仅合成匹配标签可见层，保留组变换/透明度/混合。均不含背景、尺规、参考图片和蒙版编辑线索。","enum":["current","visible","labels"]},
  "selection.similar.colorLabels":{"description":"颜色标签整数数组，1–9项且不重复，默认[1]，仅labels参考使用。0无标签，1蓝，2绿，3黄，4橙，5红，6紫，7灰，8棕；匹配非零标签组包括其可见子层，0只匹配无标签内容层。"},
  "selection.similar.opacitySpread":{"description":"覆盖硬度整数0–100%，默认100：容差内全选。降低硬度时覆盖率clamp((T-d)*255*100/[T*(100-hardness)],0,255)；T=tolerance*255/100，d为预乘RGBA最大通道差。软覆盖需要tolerance>0；boundaryMode反转覆盖曲线。"},
  "selection.similar.antialias":{"description":"边界抗锯齿强度0..1，默认1；1px十字邻域边界平滑，中心权重4、邻居各1；feather>0时跳过，避免重复平滑。"},
  "selection.similar.feather":{"description":"羽化半径整数0..32文档像素，默认0；三次盒滤波近似高斯。先扩展/收缩再羽化，之后组合。"},
  "selection.similar.expand":{"description":"扩展/收缩整数-64..64文档像素，默认0。正数扩展、负数收缩；结果裁到bounds/查找范围。"},
  "selection.similar.stopAtDarkest":{"description":"默认false，仅expand>0起效：8邻域扩展需下一像素更不透明或等透明，且更暗或等亮（上一像素全透明时不比较亮度）。不向局部暗峰后的亮区或透明度下降区传播；保留原覆盖率，最大范围仍受expand限制。不改变初始颜色搜索。"},
  "selection.similar.bounds":{"description":"可选查找范围{x,y,width,height}文档像素整数，尺寸>0；裁到画布后最多4194304像素。颜色搜索、扩展、羽化和AA都限制在此范围内。"},
  "selection.similar.limitToSelection":{"description":"默认false；true需现有选区，搜索仅用非零覆盖范围，最终覆盖率与原选区逐点取较小值。没有bounds时使用原选区外框作为查找范围。"},
  "layer.properties.colorLabel":{"description":"可选颜色标签整数0–8：0无，1蓝，2绿，3黄，4橙，5红，6紫，7灰，8棕。独立于像素颜色；可用于selection.contiguous/similar的reference=labels。"},
  "selection.bezier_create.antialias":{"description":"抗锯齿强度0–1，默认1；0关闭。feather>0时忽略此项。"},
  "selection.bezier_create.feather":{"description":"羽化半径整数0–32文档像素，默认0；扩缩之后羽化，再组合覆盖率。"},
  "selection.bezier_create.expand":{"description":"扩展/收缩整数−64至64文档像素，默认0；正数扩展，负数收缩。"},
  "selection.bezier_create.mode":{"description":"replace/add/subtract/intersect/xor，默认replace；xor覆盖率=abs(a-b)。"},
  "selection.magnetic_create.antialias":{"description":"抗锯齿强度0–1，默认1；0关闭。feather>0时忽略此项。"},
  "selection.magnetic_create.feather":{"description":"羽化半径整数0–32文档像素，默认0；扩缩之后羽化，再组合覆盖率。"},
  "selection.magnetic_create.expand":{"description":"扩展/收缩整数−64至64文档像素，默认0；正数扩展，负数收缩。"},
  "selection.magnetic_create.mode":{"description":"replace/add/subtract/intersect/xor，默认replace；xor覆盖率=abs(a-b)。"},
  "fill.contiguous.points":{"description":"512个以内的文档整数点[[x,y],...]，每项在画布内；与x/y择一。多点须dragMode=any或similar，沿折线逐像素取样，最多8192个不同像素种子。"},
  "fill.contiguous.x":{"description":"单点填充文档像素整数X；同时提供y，与points择一。首点需在搜索范围与现有选区内。"},
  "fill.contiguous.y":{"description":"单点填充文档像素整数Y；同时提供x，与points择一。"},
  "fill.contiguous.tolerance":{"description":"预乘RGBA最大通道差容差0–100%，默认0。0精确匹配；边界模式此项衡量与boundaryColor的差异。"},
  "fill.contiguous.opacitySpread":{"description":"颜色对应软覆盖硬度整数0–100%，默认100。低于100需tolerance>0；只控制颜色差异，不替代opacity。"},
  "fill.contiguous.opacity":{"description":"整个填充或擦除的透明度0–1，默认1；与颜色/图案原始透明度及软覆盖相乘，0无写入。"},
  "fill.contiguous.reference":{"description":"current/visible/labels，默认current；排除背景与参考图像等辅助内容。labels取匹配的可见内容层/带标签组。"},
  "fill.contiguous.referenceAllLayers":{"description":"旧参数，可继续使用。true=visible，false=current；若也给reference，必须一致。建议新调用使用reference。"},
  "fill.contiguous.documentId":{"description":"当前工程ID，取document.info；新调用应传入，与revision共同防止写错工程。旧单点调用可省略。"},
  "fill.contiguous.layerId":{"description":"当前目标绘画/图像层ID，取layer.list；新调用应提供以防选择变化。省略用于旧单点调用。"},
  "fill.contiguous.expectedRevision":{"description":"当前document.info.revision，替换示例0；新调用应提供。拖动在首点固定，提交时更新则拒绝写入。"},
  "fill.contiguous.gapClose":{"description":"封闭窄缺口半径整数0–32px，默认0；侵蚀阻断窄通道后恢复边缘，过大可消掉窄区域。全局相似色须0。"},
  "fill.contiguous.feather":{"description":"羽化半径整数0–32px，默认0；区域联合、扩缩之后羽化，再与选区覆盖率取最小值。"},
  "fill.contiguous.expand":{"description":"扩展/收缩整数−64至64px，默认0；正数扩展，负数收缩。仅正向扩展使用stopAtDarkest。"},
  "fill.contiguous.antialias":{"description":"边缘抗锯齿强度0–1，默认0（保留旧单点填充默认）；feather>0时只羽化，不重复抗锯齿。"},
  "fill.contiguous.erase":{"description":"默认false。true以填充内容透明度生成擦除蒙版；纯色擦除用白色满覆盖，图案擦除保留图案的透明孔洞。"},
  "fill.contiguous.bounds":{"description":"可选整数{x,y,width,height}文档搜索范围，宽高须>0且与画布相交，裁剪后最多4194304像素；所有软处理限定在此范围。"},
  "stroke.add.gradientMode":{"description":"linear投影；bilinear对投影取绝对值（两侧对称）；radial距离；square沿拖动方向旋转的方形；angular角度；symmetric_conical角度往返；spiral/reverse_spiral距离加正/反角度；shape依非零选区轮廓距离，边缘末色、每个连通岛深处首色。shape非Krita轮廓算法逐像素复刻。","enum":["linear","bilinear","radial","square","angular","symmetric_conical","spiral","reverse_spiral","shape"]},
  "stroke.add.gradientEndColor":{"description":"可选#AARRGGBB末色；省略用color全透明版本。gradientStops存在时端点色由色标定义。"},
  "gradient.draw.gradientMode":{"description":"linear投影；bilinear对投影取绝对值（两侧对称）；radial距离；square沿拖动方向旋转的方形；angular角度；symmetric_conical角度往返；spiral/reverse_spiral距离加正/反角度；shape依非零选区轮廓距离，边缘末色、每个连通岛深处首色。shape非Krita轮廓算法逐像素复刻。","enum":["linear","bilinear","radial","square","angular","symmetric_conical","spiral","reverse_spiral","shape"]},
  "gradient.draw.gradientEndColor":{"description":"可选#AARRGGBB末色；省略用color全透明版本。gradientStops存在时端点色由色标定义。"},
  "gradient.draw.points":{"description":"图层局部二维点[[x0,y0],[x1,y1]]，恰好2点，有限值±1000000，距离至少0.01px；定义方向/长度，shape仅用拖动触发。图层变换及父组会在合成时应用。"},
  "gradient.draw.layerId":{"description":"未锁定且父组未锁定的paint层ID，取layer.list；可为组内/变换层，成功仍写该层。"},
  "gradient.draw.color":{"description":"必填#AARRGGBB前景色；无gradientStops时为首色，有色标时使用色标颜色。"},
  "gradient.draw.opacity":{"description":"整个渐变透明度0–1，默认1，乘色标alpha与固定软选区覆盖一次。"},
  "patch.apply.levels":{"description":"整数0–6，默认0自动：按剩余蒙版和完整纹理补丁规划粗层；1明确单尺度，2–6指定层数。指定粗层缺少未涂抹补丁时拒绝。repair.levels返回实际计划。"},
  "patch.apply.refinementStep":{"description":"原尺寸细化点间距整数0–64，默认0按各层面积/accuracy自动选1–64；1逐像素匹配，计算量高。明确值逐层按scale换算。大值做稀疏匹配并把位移传播到像素，每个原尺寸蒙版像素仍参与纹理投票；不缩小最终输出。"},
  "patch.apply.seed":{"description":"随机种子整数0–2147483647，默认0；同一图层、蒙版和参数可重复生成相同匹配。冻结PNG重放不再计算。"},
  "reference.link.base64":{"description":"本次授权读取的图片字节Base64，最多8MiB；可省略直接读取文件/HTTPS来源。content来源后台必须提供；不是图片路径。"},
  "reference.refresh.base64":{"description":"本次授权读取的图片字节Base64，最多8MiB；可省略直接读取文件/HTTPS来源。content来源后台必须提供；不是图片路径。"},
  "reference.paste.base64":{"description":"可选系统图片数据Base64，最多8MiB；省略读取画室像素剪贴板，绝不自动改读系统剪贴板。"},
